const upsertGameVote = `-- name: UpsertGameVote :execrows
INSERT INTO game_votes (
    id,
    game_session_id,
    round_key,
    voter_player_id,
    target_player_id,
    target_role_id,
    ballot_type,
    is_abstain,
    effective_status,
    intent_id,
    event_id,
    cast_at
) VALUES (
    ?,
    ?,
    ?,
    ?,
    ?,
    ?,
    'murder_final',
    ?,
    'valid',
    ?,
    ?,
    ?
)
ON DUPLICATE KEY UPDATE
    target_player_id = VALUES(target_player_id),
    target_role_id = VALUES(target_role_id),
    is_abstain = VALUES(is_abstain),
    effective_status = VALUES(effective_status),
    intent_id = VALUES(intent_id),
    event_id = VALUES(event_id),
    cast_at = VALUES(cast_at),
    row_version = row_version + 1
`

type UpsertGameVoteParams struct {
	ID             string         `json:"id"`
	GameSessionID  string         `json:"game_session_id"`
	RoundKey       string         `json:"round_key"`
	VoterPlayerID  string         `json:"voter_player_id"`
	TargetPlayerID sql.NullString `json:"target_player_id"`
	TargetRoleID   sql.NullString `json:"target_role_id"`
	IsAbstain      bool           `json:"is_abstain"`
	IntentID       sql.NullString `json:"intent_id"`
	EventID        sql.NullString `json:"event_id"`
	CastAt         time.Time      `json:"cast_at"`
}

func (q *Queries) UpsertGameVote(ctx context.Context, arg UpsertGameVoteParams) (int64, error) {
	result, err := q.exec(ctx, q.upsertGameVoteStmt, upsertGameVote,
		arg.ID,
		arg.GameSessionID,
		arg.RoundKey,
		arg.VoterPlayerID,
		arg.TargetPlayerID,
		arg.TargetRoleID,
		arg.IsAbstain,
		arg.IntentID,
		arg.EventID,
		arg.CastAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
